#!/data/data/com.termux/files/usr/bin/bash
set -e
APP="$HOME/GEF_WL_PROXY"
BIN="$APP/client"
URL="https://github.com/MYSOREZ/vk-turn-proxy/releases/download/v1.5.3/client-android-arm64"

echo "=== GEF_WL_PROXY ==="
mkdir -p "$APP"; chmod 700 "$APP"
pkg update -y
pkg upgrade -y
pkg install -y python curl
python -m pip install textual --no-build-isolation

echo "Скачивание client-android-arm64..."
curl -fL --retry 3 "$URL" -o "$BIN"
chmod 700 "$BIN"

python - <<'PY'
import base64
from pathlib import Path
app=Path.home()/"GEF_WL_PROXY"
app.joinpath("controller.py").write_text(base64.b64decode("").decode(),encoding="utf-8")
app.joinpath("start.sh").write_text(base64.b64decode("IyEvZGF0YS9kYXRhL2NvbS50ZXJtdXgvZmlsZXMvdXNyL2Jpbi9iYXNoCmNkICIkSE9NRS9HRUZfV0xfUFJPWFkiIHx8IGV4aXQgMQpleGVjIHB5dGhvbiBjb250cm9sbGVyLnB5Cg==").decode(),encoding="utf-8")
app.joinpath("controller.py").chmod(0o700)
app.joinpath("start.sh").chmod(0o700)
PY

BASHRC="$HOME/.bashrc"
A="# >>> GEF_WL_PROXY >>>"; B="# <<< GEF_WL_PROXY <<<"
touch "$BASHRC"
awk -v a="$A" -v b="$B" '$0==a{skip=1;next}$0==b{skip=0;next}!skip{print}' "$BASHRC" > "$BASHRC.tmp"
printf '\n%s\n[ -t 1 ] && [ -z "$GEF_WL_PROXY_STARTED" ] && export GEF_WL_PROXY_STARTED=1 && exec "$HOME/GEF_WL_PROXY/start.sh"\n%s\n' "$A" "$B" >> "$BASHRC.tmp"
mv "$BASHRC.tmp" "$BASHRC"
source ~/.bashrc
echo
echo "Установка завершена."
echo "Перезапустите Termux или выполните: source ~/.bashrc"
echo "При первом запуске GEF_WL_PROXY попросит Base64-конфигурацию."
